// COMPOSANT PRINCIPAL
// ════════════════════════════════════════════════════════════════
export default function ALLO() {
  const [theme,       setTheme]       = useState("dark");
  const [screen,      setScreen]      = useState("splash");
  const A = THEMES[theme];
  const BD = A.border;
  const SH = `0 4px 20px ${A.shadow}`; // splash | main | chat | call | settings
  const [tab,         setTab]         = useState("chats");  // chats | statuts | groupes | canaux | appels
  const [chat,        setChat]        = useState(null);
  const [messages,    setMessages]    = useState(INIT_MESSAGES);
  const [inputMsg,    setInputMsg]    = useState("");
  const [replyTo,     setReplyTo]     = useState(null);
  const [activeCall,  setActiveCall]  = useState(null); // {contact, type, state}
  const [callTimer,   setCallTimer]   = useState(0);
  const [story,       setStory]       = useState(null);
  const [storyIdx,    setStoryIdx]    = useState(0);
  const [filter,      setFilter]      = useState("all");
  const [search,      setSearch]      = useState("");
  const [muteCall,    setMuteCall]    = useState(false);
  const [speakerOn,   setSpeakerOn]   = useState(false);
  const [cameraOn,    setCameraOn]    = useState(true);
  const [incomingCall,setIncomingCall]= useState(null);
  const [translating, setTranslating] = useState(null); // id du message en traduction
  const [translated,  setTranslated]  = useState({});   // {msgId: {lang, text}}
  const [showLangPicker, setShowLangPicker] = useState(null); // id msg
  const messagesEndRef = useRef(null);
  const timerRef = useRef(null);

  const getMsgs = (id) => messages[id] || [];
  const totalUnread = [...CONTACTS, ...GROUPS].reduce((s,c)=>s+(c.unread||0),0);

  // Auto-scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior:"smooth" });
  }, [messages, chat]);

  // Timer appel
  useEffect(() => {
    if (activeCall?.state === "active") {
      timerRef.current = setInterval(() => setCallTimer(t => t+1), 1000);
    } else {
      clearInterval(timerRef.current);
      setCallTimer(0);
    }
    return () => clearInterval(timerRef.current);
  }, [activeCall?.state]);

  // Appel entrant simulé
  useEffect(() => {
    if (screen === "main") {
      const t = setTimeout(() => {
        setIncomingCall({ contact: CONTACTS[0], type: "audio" });
      }, 8000);
      return () => clearTimeout(t);
    }
  }, [screen]);

  const fmtTimer = (s) => `${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;

  // Traduire un message vocal
  const translateVoice = (msgId, langCode) => {
    setShowLangPicker(null);
    setTranslating(msgId);
    setTimeout(() => {
      setTranslating(null);
      setTranslated(prev => ({
        ...prev,
        [msgId]: {
          lang: LANGUAGES.find(l=>l.code===langCode),
          text: VOICE_TRANSLATIONS[langCode] || "Traduction en cours...",
        }
      }));
    }, 1800);
  };

  const sendMessage = () => {
    if (!inputMsg.trim() || !chat) return;
    const now = new Date();
    const time = now.toLocaleTimeString("fr",{hour:"2-digit",minute:"2-digit"});
    const msg = {
      id: Date.now(),
      from: "me",
      text: inputMsg.trim(),
      time,
      date: "Aujourd'hui",
      read: false,
      replyTo: replyTo?.id || null,
    };
    setMessages(prev => ({ ...prev, [chat.id]: [...getMsgs(chat.id), msg] }));
    setInputMsg("");
    setReplyTo(null);
    // Réponse auto
    setTimeout(() => {
      const auto = {
        id: Date.now()+1,
        from: "them",
        text: ["👍 Reçu !","Ok merci 🙏","Je t'appelle dans 5 min","🔥 Super !","D'accord, je note."][Math.floor(Math.random()*5)],
        time: now.toLocaleTimeString("fr",{hour:"2-digit",minute:"2-digit"}),
        date: "Aujourd'hui",
        read: true,
      };
      setMessages(prev => ({ ...prev, [chat.id]: [...getMsgs(chat.id), msg, auto] }));
    }, 1500);
  };

  const startCall = (contact, type) => {
    setActiveCall({ contact, type, state: "calling" });
    setScreen("call");
    setTimeout(() => setActiveCall(c => c ? {...c, state:"active"} : null), 3000);
  };

  const endCall = () => {
    setActiveCall(null);
    setScreen(chat ? "chat" : "main");
  };

  const openChat = (c) => { setChat(c); setScreen("chat"); };
  const openStory = (s, idx) => { setStory(s); setStoryIdx(idx); };

  // ── SPLASH ──────────────────────────────────────────────────
  if (screen === "splash") return (
    <div style={{minHeight:"100vh",background:A.gradHero,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:"40px 28px",position:"relative",overflow:"hidden"}}>
      {/* Halos */}
      <div style={{position:"absolute",width:400,height:400,borderRadius:"50%",background:"radial-gradient(circle,rgba(123,104,238,0.12),transparent 70%)",top:-100,left:"50%",transform:"translateX(-50%)"}}/>
      <div style={{position:"absolute",width:300,height:300,borderRadius:"50%",background:"radial-gradient(circle,rgba(167,139,250,0.08),transparent 70%)",bottom:-80,right:-60}}/>

      <div style={{position:"relative",zIndex:1,textAlign:"center",width:"100%"}}>
        {/* Logo */}
        <img src={LOGO_SPLASH} style={{width:220,height:220,objectFit:"contain",borderRadius:44,boxShadow:"0 12px 48px rgba(123,104,238,0.4)"}} alt="ALLO"/>
        <div style={{fontSize:13,color:A.muted,letterSpacing:2,marginBottom:48}}>Messagerie chiffrée · Afrique</div>

        {/* Stats */}
        <div style={{display:"flex",gap:12,justifyContent:"center",marginBottom:48}}>
          {[{v:"AES-256",l:"Chiffrement"},{v:"E2E",l:"Bout en bout"},{v:"0",l:"Donnée vendue"}].map((s,i)=>(
            <div key={i} style={{background:"rgba(123,104,238,0.1)",border:`1px solid rgba(123,104,238,0.2)`,borderRadius:16,padding:"12px 14px",textAlign:"center"}}>
              <div style={{fontSize:16,fontWeight:900,color:A.accent}}>{s.v}</div>
              <div style={{fontSize:10,color:A.muted,marginTop:2}}>{s.l}</div>
            </div>
          ))}
        </div>

        {/* Bouton */}

        <button onClick={()=>setScreen("main")}
          style={{width:"100%",background:A.grad,border:"none",borderRadius:20,padding:"17px",fontSize:16,fontWeight:900,color:"#fff",cursor:"pointer",boxShadow:`0 8px 28px rgba(123,104,238,0.45)`}}>
          Commencer →
        </button>
        <div style={{fontSize:11,color:A.muted,marginTop:14}}>🔒 Aucune donnée personnelle collectée</div>
      </div>
    </div>
  );

  // ── CALL SCREEN ──────────────────────────────────────────────
  if (screen === "call" && activeCall) {
    const c = activeCall.contact;
    const isVideo = activeCall.type === "video";
    const isActive = activeCall.state === "active";
    const isCalling = activeCall.state === "calling";
    return (
      <div style={{minHeight:"100vh",background:isVideo?"#000":`linear-gradient(160deg,#0F1628 0%,#1a1060 50%,#2d1b8a 100%)`,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"space-between",padding:"60px 24px 50px",position:"relative",overflow:"hidden"}}>
        {/* Fond vidéo simulé */}
        {isVideo && <div style={{position:"absolute",inset:0,background:`linear-gradient(135deg,${c.bg.replace("linear-gradient(135deg,","").replace(")","")},transparent)`,opacity:0.4}}/>}
        {/* Halo animé */}
        {!isVideo && [1,2,3].map(i=>(
          <div key={i} style={{position:"absolute",width:i*120+80,height:i*120+80,borderRadius:"50%",border:"1.5px solid rgba(123,104,238,0.15)",top:"50%",left:"50%",transform:"translate(-50%,-50%)",animation:`pulse ${1+i*0.4}s ease-in-out infinite`}}/>
        ))}

        {/* Info */}
        <div style={{textAlign:"center",position:"relative",zIndex:1}}>
          <div style={{fontSize:12,color:"rgba(255,255,255,0.6)",marginBottom:16,letterSpacing:1}}>
            {isVideo?"📹 Appel vidéo":"📞 Appel audio"} · 🔒 Chiffré E2E
          </div>
          {/* Avatar */}
          <div style={{width:120,height:120,borderRadius:isVideo?24:"50%",background:c.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:52,margin:"0 auto 18px",boxShadow:`0 12px 40px rgba(0,0,0,0.5)`,animation:isCalling?"callPulse 1.5s infinite":"none"}}>
            {c.emoji}
          </div>
          <div style={{fontSize:24,fontWeight:900,color:"#fff",marginBottom:6}}>{c.name}</div>
          <div style={{fontSize:15,color:"rgba(255,255,255,0.7)",fontWeight:600}}>
            {isCalling?"Appel en cours...":isActive?fmtTimer(callTimer):"Connexion..."}
          </div>
        </div>

        {/* Boutons secondaires */}
        <div style={{display:"flex",gap:16,justifyContent:"center",position:"relative",zIndex:1}}>
          {[
            {icon:muteCall?"🔇":"🎤",   label:muteCall?"Muet":"Son",     action:()=>setMuteCall(m=>!m),   active:muteCall},
            {icon:speakerOn?"📢":"🔈",  label:"HP",                       action:()=>setSpeakerOn(s=>!s),  active:speakerOn},
            {icon:isVideo?(cameraOn?"📷":"📵"):"📹",label:isVideo?"Cam":"Vidéo",action:()=>setCameraOn(c=>!c),active:!cameraOn&&isVideo},
            {icon:"⌨️",                 label:"Clavier",                  action:()=>{},                   active:false},
          ].map((b,i)=>(
            <div key={i} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6}}>
              <button onClick={b.action}
                style={{width:56,height:56,borderRadius:"50%",background:b.active?"rgba(123,104,238,0.4)":"rgba(255,255,255,0.1)",backdropFilter:"blur(10px)",border:`1px solid ${b.active?"rgba(123,104,238,0.5)":"rgba(255,255,255,0.15)"}`,fontSize:24,cursor:"pointer",transition:"all 0.2s"}}>
                {b.icon}
              </button>
              <span style={{fontSize:10,color:"rgba(255,255,255,0.6)",fontWeight:600}}>{b.label}</span>
            </div>
          ))}
        </div>

        {/* Boutons principaux */}
        <div style={{display:"flex",gap:28,justifyContent:"center",position:"relative",zIndex:1}}>
          {isCalling && (
            <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:8}}>
              <button onClick={()=>setActiveCall(c=>({...c,state:"active"}))}
                style={{width:70,height:70,borderRadius:"50%",background:"linear-gradient(135deg,#00C853,#00A86B)",border:"none",fontSize:28,cursor:"pointer",boxShadow:"0 6px 24px rgba(0,200,83,0.45)"}}>
                📞
              </button>
              <span style={{fontSize:11,color:"rgba(255,255,255,0.6)",fontWeight:600}}>Répondre</span>
            </div>
          )}
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:8}}>
            <button onClick={endCall}
              style={{width:70,height:70,borderRadius:"50%",background:"linear-gradient(135deg,#FF5252,#D32F2F)",border:"none",fontSize:28,cursor:"pointer",boxShadow:"0 6px 24px rgba(255,82,82,0.45)"}}>
              📵
            </button>
            <span style={{fontSize:11,color:"rgba(255,255,255,0.6)",fontWeight:600}}>Raccrocher</span>
          </div>
        </div>

        <style>{`@keyframes callPulse{0%,100%{box-shadow:0 0 0 0 rgba(123,104,238,0.4)}50%{box-shadow:0 0 0 20px rgba(123,104,238,0)}} @keyframes pulse{0%,100%{opacity:0.4;transform:translate(-50%,-50%) scale(1)}50%{opacity:0.8;transform:translate(-50%,-50%) scale(1.05)}}`}</style>
      </div>
    );
  }

  // ── STORY VIEWER ─────────────────────────────────────────────
  if (story) {
    const stories = STORIES.filter(s=>!s.isMe);
    const cur = stories[storyIdx] || story;
    return (
      <div style={{position:"fixed",inset:0,background:"#000",zIndex:200,display:"flex",flexDirection:"column"}}
        onClick={()=>storyIdx<stories.length-1?setStoryIdx(i=>i+1):setStory(null)}>
        {/* Barres */}
        <div style={{position:"absolute",top:0,left:0,right:0,padding:"12px 10px 0",display:"flex",gap:4,zIndex:10}}>
          {stories.map((_,i)=>(
            <div key={i} style={{flex:1,height:3,borderRadius:2,background:"rgba(255,255,255,0.3)",overflow:"hidden"}}>
              <div style={{height:"100%",background:"#fff",width:i<storyIdx?"100%":i===storyIdx?"60%":"0%"}}/>
            </div>
          ))}
        </div>
        {/* Header */}
        <div style={{position:"absolute",top:20,left:14,right:14,zIndex:10,display:"flex",alignItems:"center",gap:10}}>
          <div style={{width:38,height:38,borderRadius:"50%",background:cur.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,border:"2px solid rgba(255,255,255,0.6)"}}>{cur.emoji}</div>
          <div style={{flex:1}}>
            <div style={{fontSize:13,fontWeight:700,color:"#fff"}}>{cur.name}</div>
            <div style={{fontSize:11,color:"rgba(255,255,255,0.6)"}}>{cur.time}</div>
          </div>
          <button onClick={(e)=>{e.stopPropagation();setStory(null);}} style={{background:"none",border:"none",color:"#fff",fontSize:24,cursor:"pointer"}}>×</button>
        </div>
        {/* Contenu */}
        <div style={{flex:1,background:cur.bg,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:20}}>
          <div style={{fontSize:80}}>{cur.emoji}</div>
          <div style={{fontSize:22,fontWeight:800,color:"#fff",textAlign:"center",padding:"0 32px"}}>{cur.content}</div>
        </div>
        {/* Réponse */}
        <div style={{padding:"12px 14px 32px",background:"rgba(0,0,0,0.5)",backdropFilter:"blur(20px)",display:"flex",gap:10,alignItems:"center"}} onClick={e=>e.stopPropagation()}>
          <input placeholder={"Répondre à "+cur.name+"..."}
            style={{flex:1,background:"rgba(255,255,255,0.1)",border:"1px solid rgba(255,255,255,0.2)",borderRadius:24,padding:"10px 16px",fontSize:13,color:"#fff",outline:"none"}}/>
          <div style={{display:"flex",gap:8}}>
            {["❤️","🔥","👏"].map((e,i)=>(
              <button key={i} style={{background:"none",border:"none",fontSize:24,cursor:"pointer"}}>{e}</button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // ── CHAT SCREEN ───────────────────────────────────────────────
  if (screen === "chat" && chat) {
    const msgs = getMsgs(chat.id);
    return (
      <div style={{height:"100vh",background:A.bg,display:"flex",flexDirection:"column",position:"relative",transition:"background 0.3s ease"}}>
        {/* Header */}
        <div style={{background:A.gradCard,padding:"46px 14px 12px",display:"flex",alignItems:"center",gap:12,borderBottom:`1px solid ${BD}`,flexShrink:0}}>
          <button onClick={()=>setScreen("main")} style={{background:"none",border:"none",color:A.text,fontSize:22,cursor:"pointer",padding:"4px"}}>←</button>
          <div style={{width:42,height:42,borderRadius:"50%",background:chat.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0,position:"relative"}}>
            {chat.emoji}
            {chat.online && <div style={{position:"absolute",bottom:1,right:1,width:11,height:11,borderRadius:"50%",background:A.green,border:`2px solid ${A.card}`}}/>}
          </div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:15,fontWeight:800,color:A.text}}>{chat.name}</div>
            <div style={{fontSize:11,color:chat.online?A.green:A.muted}}>{chat.online?"En ligne · 🔒 E2E":"Hors ligne"}{chat.members?` · ${chat.members} membres`:""}</div>
          </div>
          <div style={{display:"flex",gap:8}}>
            <button onClick={()=>startCall(chat,"video")} style={{background:`rgba(123,104,238,0.12)`,border:`1px solid ${BD}`,borderRadius:12,width:38,height:38,fontSize:18,cursor:"pointer"}}>📹</button>
            <button onClick={()=>startCall(chat,"audio")} style={{background:`rgba(123,104,238,0.12)`,border:`1px solid ${BD}`,borderRadius:12,width:38,height:38,fontSize:18,cursor:"pointer"}}>📞</button>
            <button style={{background:`rgba(123,104,238,0.12)`,border:`1px solid ${BD}`,borderRadius:12,width:38,height:38,fontSize:18,cursor:"pointer"}}>⋮</button>
          </div>
        </div>

        {/* Zone messages */}
        <div style={{flex:1,overflowY:"auto",padding:"10px 10px 8px",display:"flex",flexDirection:"column",gap:4,
          backgroundImage:"radial-gradient(circle at 15% 15%,rgba(123,104,238,0.05) 0%,transparent 40%),radial-gradient(circle at 85% 85%,rgba(167,139,250,0.04) 0%,transparent 40%)",
          backgroundColor:A.msgBg,backgroundImage:A.chatBg}}>
          {/* Note E2E */}
          <div style={{textAlign:"center",margin:"8px 0 12px"}}>
            <span style={{background:"rgba(123,104,238,0.1)",color:"rgba(167,139,250,0.8)",fontSize:11,fontWeight:600,padding:"5px 14px",borderRadius:20,border:`1px solid rgba(123,104,238,0.15)`}}>
              🔒 Messages chiffrés de bout en bout · ALLO
            </span>
          </div>

          {/* Messages */}
          {msgs.map((msg, i) => {
            const isMe = msg.from === "me";
            const prev = msgs[i-1];
            const showAvatar = !isMe && (!prev || prev.from === "me");
            const replyMsg = msg.replyTo ? msgs.find(m=>m.id===msg.replyTo) : null;

            return (
              <div key={msg.id} style={{display:"flex",flexDirection:"column",alignItems:isMe?"flex-end":"flex-start",marginBottom:4}}
                onDoubleClick={()=>setReplyTo(msg)}>
                <div style={{display:"flex",alignItems:"flex-end",gap:6,maxWidth:"82%"}}>
                  {/* Avatar */}
                  {!isMe && (
                    <div style={{width:28,height:28,borderRadius:"50%",background:showAvatar?chat.bg:"transparent",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,flexShrink:0,marginBottom:2,visibility:showAvatar?"visible":"hidden"}}>
                      {showAvatar?chat.emoji:""}
                    </div>
                  )}
                  {/* Bulle */}
                  <div style={{
                    background:isMe?A.grad:A.bubble_in,
                    borderRadius:isMe?"18px 18px 4px 18px":"4px 18px 18px 18px",
                    padding:"9px 13px 7px",
                    boxShadow:isMe?`0 2px 10px rgba(108,92,231,0.35)`:`0 2px 8px rgba(0,0,0,0.3)`,
                    border:isMe?"none":`1px solid rgba(123,104,238,0.15)`,
                    position:"relative",
                    maxWidth:"100%",
                  }}>
                    {/* Nom dans groupe */}
                    {!isMe && msg.name && (
                      <div style={{fontSize:11,fontWeight:700,color:A.accent2,marginBottom:3}}>{msg.name}</div>
                    )}
                    {/* Reply preview */}
                    {replyMsg && (
                      <div style={{background:"rgba(0,0,0,0.2)",borderLeft:`3px solid ${A.accent2}`,borderRadius:"0 8px 8px 0",padding:"5px 10px",marginBottom:6}}>
                        <div style={{fontSize:10,fontWeight:700,color:A.accent2,marginBottom:2}}>{replyMsg.from==="me"?"Vous":"Interlocuteur"}</div>
                        <div style={{fontSize:11,color:"rgba(232,238,255,0.6)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{replyMsg.text||"Message"}</div>
                      </div>
                    )}
                    {/* Contenu */}
                    {msg.type === "voice" ? (
                      <div style={{minWidth:180}}>
                        {/* Lecteur vocal */}
                        <div style={{display:"flex",alignItems:"center",gap:8}}>
                          <button style={{width:34,height:34,borderRadius:"50%",background:"rgba(255,255,255,0.2)",border:"none",fontSize:15,cursor:"pointer",flexShrink:0}}>▶</button>
                          <div style={{flex:1,display:"flex",alignItems:"center",gap:2,height:26}}>
                            {[3,7,11,6,13,5,10,12,4,8,9,6].map((h,vi)=>(
                              <div key={vi} style={{width:3,height:h,borderRadius:2,background:isMe?"rgba(255,255,255,0.6)":A.accent,opacity:0.8}}/>
                            ))}
                          </div>
                          <span style={{fontSize:11,color:isMe?"rgba(255,255,255,0.6)":A.muted,flexShrink:0}}>{msg.duration||30}s</span>
                        </div>

                        {/* Traduction reçue */}
                        {translated[msg.id] && (
                          <div style={{marginTop:8,padding:"8px 10px",background:isMe?"rgba(0,0,0,0.15)":"rgba(123,104,238,0.12)",borderRadius:10,borderLeft:`3px solid ${A.accent}`}}>
                            <div style={{fontSize:10,fontWeight:700,color:A.accent,marginBottom:3}}>
                              {translated[msg.id].lang?.flag} Traduit en {translated[msg.id].lang?.name}
                            </div>
                            <div style={{fontSize:12,color:isMe?"rgba(255,255,255,0.85)":A.text,lineHeight:1.4}}>
                              {translated[msg.id].text}
                            </div>
                          </div>
                        )}

                        {/* Indicateur de traduction en cours */}
                        {translating===msg.id && (
                          <div style={{marginTop:8,display:"flex",alignItems:"center",gap:6}}>
                            <div style={{display:"flex",gap:3}}>
                              {[0,1,2].map(di=>(
                                <div key={di} style={{width:6,height:6,borderRadius:"50%",background:A.accent,animation:`typingDot 1.2s ${di*0.2}s ease-in-out infinite`}}/>
                              ))}
                            </div>
                            <span style={{fontSize:11,color:A.muted}}>Traduction en cours...</span>
                          </div>
                        )}

                        {/* Bouton traduire — seulement si pas encore traduit */}
                        {!translated[msg.id] && translating!==msg.id && !isMe && (
                          <div style={{marginTop:8}}>
                            <button onClick={()=>setShowLangPicker(msg.id)}
                              style={{background:`${A.accent}18`,border:`1px solid ${A.border}`,borderRadius:20,padding:"4px 12px",fontSize:11,fontWeight:700,color:A.accent,cursor:"pointer",display:"flex",alignItems:"center",gap:5}}>
                              🌍 Traduire
                            </button>
                          </div>
                        )}
                      </div>
                    ) : (
                      <div style={{fontSize:14,color:A.text,lineHeight:1.55,wordBreak:"break-word"}}>{msg.text}</div>
                    )}
                    {/* Meta */}
                    <div style={{display:"flex",alignItems:"center",justifyContent:"flex-end",gap:3,marginTop:3,float:"right",marginLeft:8}}>
                      <span style={{fontSize:9,color:"rgba(255,255,255,0.2)"}}>🔒</span>
                      <span style={{fontSize:10,color:"rgba(255,255,255,0.5)",whiteSpace:"nowrap"}}>{msg.time}</span>
                      {isMe && <span style={{fontSize:11,color:msg.read?A.accent2:"rgba(255,255,255,0.4)"}}>{msg.read?"✓✓":"✓"}</span>}
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
          <div ref={messagesEndRef}/>
        </div>

        {/* Barre de réponse */}
        {replyTo && (
          <div style={{background:A.input,borderLeft:`3px solid ${A.accent}`,padding:"8px 12px",display:"flex",justifyContent:"space-between",alignItems:"center",flexShrink:0}}>
            <div>
              <div style={{fontSize:11,fontWeight:700,color:A.accent,marginBottom:2}}>Répondre à {replyTo.from==="me"?"vous-même":"l'interlocuteur"}</div>
              <div style={{fontSize:12,color:"rgba(232,238,255,0.6)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:260}}>{replyTo.text}</div>
            </div>
            <button onClick={()=>setReplyTo(null)} style={{background:"none",border:"none",color:"rgba(232,238,255,0.4)",fontSize:20,cursor:"pointer"}}>×</button>
          </div>
        )}

        {/* Input */}
        <div style={{background:A.card,borderTop:`1px solid ${BD}`,padding:"8px 10px 24px",display:"flex",alignItems:"flex-end",gap:8,flexShrink:0}}>
          <button style={{background:"none",border:"none",fontSize:22,cursor:"pointer",opacity:0.7,flexShrink:0}}>😊</button>
          <div style={{flex:1,background:A.input,border:`1.5px solid ${BD}`,borderRadius:24,display:"flex",alignItems:"center",padding:"0 12px",minHeight:44}}>
            <input value={inputMsg} onChange={e=>setInputMsg(e.target.value)}
              onKeyDown={e=>e.key==="Enter"&&!e.shiftKey&&sendMessage()}
              placeholder="Message..."
              style={{flex:1,background:"none",border:"none",color:A.text,fontSize:14,outline:"none",padding:"10px 0"}}/>
            <button style={{background:"none",border:"none",fontSize:20,cursor:"pointer",opacity:0.7}}>📎</button>
          </div>
          <button onClick={sendMessage}
            style={{width:46,height:46,borderRadius:"50%",background:inputMsg.trim()?A.grad:"rgba(123,104,238,0.2)",border:"none",fontSize:20,cursor:"pointer",color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,transition:"all 0.2s",boxShadow:inputMsg.trim()?`0 4px 16px rgba(123,104,238,0.4)`:"none"}}>
            {inputMsg.trim()?"➤":"🎤"}
          </button>
        </div>
      </div>
    );
  }

  // ── MAIN SCREEN ───────────────────────────────────────────────
  const allChats = [...CONTACTS, ...GROUPS].filter(c => {
    if (filter === "unread") return c.unread > 0;
    if (filter === "groups") return c.members !== undefined;
    return true;
  }).filter(c => !search || c.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div style={{height:"100vh",background:A.bg,display:"flex",flexDirection:"column",position:"relative",overflow:"hidden",transition:"background 0.3s ease"}}>
      {/* Appel entrant */}
      {incomingCall && (
        <div style={{position:"fixed",bottom:20,left:"50%",transform:"translateX(-50%)",width:"calc(100% - 32px)",maxWidth:430,background:"linear-gradient(135deg,#141D35,#1E2A4A)",border:`1px solid rgba(123,104,238,0.3)`,borderRadius:24,padding:18,zIndex:400,boxShadow:`0 12px 40px rgba(0,0,0,0.6)`}}>
          <div style={{display:"flex",alignItems:"center",gap:14}}>
            <div style={{width:52,height:52,borderRadius:18,background:incomingCall.contact.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,flexShrink:0,animation:"callPulse 1.5s infinite"}}>{incomingCall.contact.emoji}</div>
            <div style={{flex:1}}>
              <div style={{fontSize:16,fontWeight:800,color:A.text,marginBottom:2}}>{incomingCall.contact.name}</div>
              <div style={{fontSize:12,color:A.muted}}>📞 Appel entrant · ALLO</div>
            </div>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>{setIncomingCall(null);startCall(incomingCall.contact,incomingCall.type);}}
                style={{width:52,height:52,borderRadius:"50%",background:"linear-gradient(135deg,#00C853,#00A86B)",border:"none",fontSize:24,cursor:"pointer",boxShadow:"0 4px 16px rgba(0,200,83,0.4)"}}>📞</button>
              <button onClick={()=>setIncomingCall(null)}
                style={{width:52,height:52,borderRadius:"50%",background:"linear-gradient(135deg,#FF5252,#D32F2F)",border:"none",fontSize:24,cursor:"pointer",boxShadow:"0 4px 16px rgba(255,82,82,0.4)"}}>📵</button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div style={{background:A.gradCard,borderBottom:`1px solid ${BD}`,flexShrink:0}}>
        <div style={{padding:"46px 16px 10px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            {tab==="params" ? (
            <div style={{display:"flex",alignItems:"center",gap:10}}>
              <button onClick={()=>setTab("chats")} style={{background:"none",border:"none",color:A.text,fontSize:20,cursor:"pointer",padding:"4px"}}>←</button>
              <span style={{fontSize:17,fontWeight:800,color:A.text}}>Paramètres</span>
            </div>
          ) : (
            <img src={LOGO_ICON} style={{height:40,width:40,objectFit:"contain",borderRadius:10}} alt="Allô"/>
          )}
            {totalUnread>0 && <div style={{background:A.accent,color:"#fff",borderRadius:20,padding:"2px 8px",fontSize:11,fontWeight:800}}>{totalUnread}</div>}
          </div>
          <div style={{display:"flex",gap:8,alignItems:"center"}}>
            <div style={{width:8,height:8,borderRadius:"50%",background:A.green,boxShadow:`0 0 8px ${A.green}`}}/>
            <button style={{background:`rgba(123,104,238,0.12)`,border:`1px solid ${BD}`,borderRadius:12,width:36,height:36,fontSize:16,cursor:"pointer",color:A.text}}>📷</button>
            <button onClick={()=>setTab("params")}
            style={{background:tab==="params"?A.grad:`rgba(123,104,238,0.12)`,border:`1px solid ${BD}`,borderRadius:12,width:36,height:36,fontSize:16,cursor:"pointer",color:tab==="params"?"#fff":A.text,transition:"all 0.2s"}}>⚙️</button>
          </div>
        </div>

        {/* Tabs */}
        <div style={{display:"flex",overflowX:"auto",padding:"0 16px",gap:0,scrollbarWidth:"none"}}>
          {[{k:"chats",l:"💬 Chats"},{k:"statuts",l:"👁️ Statuts"},{k:"groupes",l:"👥 Groupes"},{k:"canaux",l:"📢 Canaux"},{k:"appels",l:"📞 Appels"}].map(t=>(
            <button key={t.k} onClick={()=>setTab(t.k)}
              style={{flexShrink:0,background:"none",border:"none",borderBottom:`3px solid ${tab===t.k?A.accent:"transparent"}`,padding:"10px 12px",fontSize:12,fontWeight:700,color:tab===t.k?A.accent:"rgba(168,178,209,0.6)",cursor:"pointer",whiteSpace:"nowrap",transition:"all 0.2s"}}>
              {t.l}
            </button>
          ))}
        </div>
      </div>

      {/* Contenu tabs */}
      <div style={{flex:1,overflowY:"auto"}}>

        {/* ── CHATS ── */}
        {tab==="chats" && (
          <>
            {/* Recherche + Filtres */}
            <div style={{padding:"10px 14px 4px"}}>
              <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Rechercher..."
                style={{width:"100%",background:A.input,border:`1px solid ${BD}`,borderRadius:14,padding:"10px 16px",fontSize:13,color:A.text,outline:"none"}}/>
            </div>
            <div style={{display:"flex",gap:8,padding:"8px 14px",overflowX:"auto",scrollbarWidth:"none"}}>
              {[{k:"all",l:"Toutes"},{k:"unread",l:"Non lues"},{k:"groups",l:"Groupes"},{k:"favorites",l:"Favoris"}].map(f=>(
                <button key={f.k} onClick={()=>setFilter(f.k)}
                  style={{flexShrink:0,background:filter===f.k?A.accent:"transparent",border:`1.5px solid ${filter===f.k?A.accent:BD}`,borderRadius:20,padding:"5px 14px",fontSize:12,fontWeight:700,color:filter===f.k?"#fff":A.muted,cursor:"pointer",transition:"all 0.2s"}}>
                  {f.l}
                </button>
              ))}
            </div>



            {/* Liste conversations */}
            {allChats.map((c,i)=>(
              <div key={c.id} onClick={()=>openChat(c)}
                style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",cursor:"pointer",borderBottom:`1px solid rgba(123,104,238,0.06)`,transition:"background 0.15s"}}
                onMouseEnter={e=>e.currentTarget.style.background="rgba(123,104,238,0.04)"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <div style={{position:"relative",flexShrink:0}}>
                  <div style={{width:50,height:50,borderRadius:"50%",background:c.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:24}}>
                    {c.emoji}
                  </div>
                  {c.online && <div style={{position:"absolute",bottom:1,right:1,width:12,height:12,borderRadius:"50%",background:A.green,border:`2px solid ${A.bg}`}}/>}
                </div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
                    <span style={{fontSize:14,fontWeight:700,color:A.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:"65%"}}>
                      {c.name}
                      {c.verified && <span style={{fontSize:12,color:A.accent,marginLeft:4}}>✓</span>}
                    </span>
                    <span style={{fontSize:11,color:c.unread>0?A.accent:A.muted,flexShrink:0,fontWeight:c.unread>0?700:400}}>{c.time}</span>
                  </div>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                    <span style={{fontSize:12,color:A.muted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>{c.last}</span>
                    {c.unread>0 && <div style={{width:20,height:20,borderRadius:"50%",background:A.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:800,color:"#fff",flexShrink:0,marginLeft:6}}>{c.unread}</div>}
                  </div>
                </div>
              </div>
            ))}
          </>
        )}

        {/* ── STATUTS ── */}
        {tab==="statuts" && (
          <div>
            <div style={{padding:"14px 16px 6px",fontSize:11,fontWeight:700,color:A.muted,letterSpacing:0.8}}>RÉCENTS</div>
            {STORIES.filter(s=>!s.isMe).map(s=>(
              <div key={s.id} onClick={()=>openStory(s,STORIES.filter(x=>!x.isMe).indexOf(s))}
                style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",cursor:"pointer",borderBottom:`1px solid ${BD}`}}>
                <div style={{width:52,height:52,borderRadius:"50%",padding:2,background:s.seen?"rgba(255,255,255,0.1)":`linear-gradient(135deg,${A.accent},${A.accent2})`}}>
                  <div style={{width:"100%",height:"100%",borderRadius:"50%",background:s.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:24,border:`2px solid ${A.bg}`}}>{s.emoji}</div>
                </div>
                <div style={{flex:1}}>
                  <div style={{fontSize:14,fontWeight:700,color:A.text,marginBottom:2}}>{s.name}</div>
                  <div style={{fontSize:12,color:A.muted}}>{s.time} · {s.content?.substring(0,35)}...</div>
                </div>
              </div>
            ))}
            <div style={{padding:"14px 16px"}}>
              <button style={{width:"100%",background:A.grad,border:"none",borderRadius:16,padding:"13px",fontSize:14,fontWeight:700,color:"#fff",cursor:"pointer",boxShadow:`0 4px 16px rgba(123,104,238,0.35)`}}>
                + Ajouter mon statut
              </button>
            </div>
          </div>
        )}

        {/* ── GROUPES ── */}
        {tab==="groupes" && (
          <div>
            <div style={{padding:"12px 14px"}}>
              <button style={{width:"100%",background:`rgba(123,104,238,0.08)`,border:`1.5px dashed rgba(123,104,238,0.25)`,borderRadius:16,padding:"12px",fontSize:13,fontWeight:700,color:A.accent,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
                <span style={{fontSize:20}}>➕</span> Créer un groupe
              </button>
            </div>
            <div style={{padding:"0 16px 6px",fontSize:11,fontWeight:700,color:A.muted,letterSpacing:0.8}}>MES GROUPES</div>
            {GROUPS.map(g=>(
              <div key={g.id} onClick={()=>openChat(g)}
                style={{display:"flex",alignItems:"center",gap:12,padding:"14px 16px",cursor:"pointer",borderBottom:`1px solid ${BD}`,transition:"background 0.15s"}}
                onMouseEnter={e=>e.currentTarget.style.background="rgba(123,104,238,0.04)"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <div style={{width:52,height:52,borderRadius:18,background:g.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,flexShrink:0}}>{g.emoji}</div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
                    <span style={{fontSize:14,fontWeight:700,color:A.text}}>{g.name}</span>
                    <span style={{fontSize:11,color:g.unread>0?A.accent:A.muted}}>{g.time}</span>
                  </div>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                    <span style={{fontSize:12,color:A.muted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>{g.last}</span>
                    {g.unread>0 ? <div style={{width:20,height:20,borderRadius:"50%",background:A.accent,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:800,color:"#fff",flexShrink:0}}>{g.unread}</div>
                    : <span style={{fontSize:11,color:A.muted,flexShrink:0}}>👥 {g.members}</span>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* ── CANAUX ── */}
        {tab==="canaux" && (
          <div>
            <div style={{padding:"12px 14px 6px",fontSize:11,fontWeight:700,color:A.muted,letterSpacing:0.8}}>POPULAIRES 🇨🇮</div>
            {CHANNELS.map(c=>(
              <div key={c.id}
                style={{display:"flex",alignItems:"center",gap:12,padding:"14px 16px",cursor:"pointer",borderBottom:`1px solid ${BD}`,transition:"background 0.15s"}}
                onMouseEnter={e=>e.currentTarget.style.background="rgba(123,104,238,0.04)"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <div style={{width:52,height:52,borderRadius:18,background:c.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,flexShrink:0}}>{c.emoji}</div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}>
                    <span style={{fontSize:14,fontWeight:700,color:A.text}}>
                      {c.name}
                      {c.verified && <span style={{fontSize:12,color:A.accent,marginLeft:4}}>✓</span>}
                    </span>
                    <span style={{fontSize:11,color:A.muted}}>{c.time}</span>
                  </div>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                    <span style={{fontSize:12,color:A.muted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>{c.last}</span>
                    <span style={{fontSize:11,color:A.muted,flexShrink:0,marginLeft:6}}>{c.subs}</span>
                  </div>
                </div>
                <button style={{background:A.grad,border:"none",borderRadius:12,padding:"6px 12px",fontSize:11,fontWeight:700,color:"#fff",cursor:"pointer",flexShrink:0}}>+ Suivre</button>
              </div>
            ))}
          </div>
        )}

        {/* ── APPELS ── */}
        {tab==="appels" && (
          <div>
            <div style={{padding:"10px 14px 6px",fontSize:11,fontWeight:700,color:A.muted,letterSpacing:0.8}}>RÉCENTS</div>
            {CALLS_HISTORY.map((call,i)=>(
              <div key={call.id} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 16px",borderBottom:`1px solid ${BD}`}}>
                <div style={{width:46,height:46,borderRadius:"50%",background:call.contact.bg,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22,flexShrink:0}}>{call.contact.emoji}</div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:14,fontWeight:700,color:A.text,marginBottom:2}}>{call.contact.name}</div>
                  <div style={{fontSize:12,color:call.missed?"#FF5252":A.muted}}>
                    {call.type==="video"?"📹":"📞"}
                    {call.direction==="in"?" ↙️ Entrant":" ↗️ Sortant"}
                    {call.missed?" · Manqué":""}
                    {call.duration?" · "+call.duration:""}
                    {" · "+call.time}
                  </div>
                </div>
                <div style={{display:"flex",gap:8,flexShrink:0}}>
                  <button onClick={()=>startCall(call.contact,"audio")}
                    style={{background:`rgba(123,104,238,0.12)`,border:`1px solid ${BD}`,borderRadius:12,width:36,height:36,fontSize:16,cursor:"pointer"}}>📞</button>
                  <button onClick={()=>startCall(call.contact,"video")}
                    style={{background:`rgba(123,104,238,0.12)`,border:`1px solid ${BD}`,borderRadius:12,width:36,height:36,fontSize:16,cursor:"pointer"}}>📹</button>
                </div>
              </div>
            ))}
            <div style={{padding:"20px 16px",textAlign:"center"}}>
              <div style={{fontSize:28,marginBottom:8}}>🔒</div>
              <div style={{fontSize:14,fontWeight:700,color:A.text,marginBottom:4}}>Appels chiffrés E2E</div>
              <div style={{fontSize:12,color:A.muted}}>Vos appels sont protégés par AES-256</div>
            </div>
          </div>
        )}
      </div>



      <style>{`
        * { box-sizing: border-box; }
        body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, 'Inter', sans-serif; }
        ::-webkit-scrollbar { width: 0; }
        input::placeholder { color: ${A.muted}; }
        @keyframes typingDot { 0%,60%,100%{transform:translateY(0);opacity:0.4} 30%{transform:translateY(-5px);opacity:1} }
        @keyframes callPulse { 0%,100%{box-shadow:0 0 0 0 rgba(123,104,238,0.4)} 50%{box-shadow:0 0 0 16px rgba(123,104,238,0)} }
      `}</style>
    </div>
  );
}
